local a={Url="https://raw.githubusercontent.com/cookieys/loader/refs/heads/main/Games.lua",Retries=3,Debug=true}local b=syn and syn.request or http and http.request or http_request or fluxus and fluxus.request or request;local function c(d,e)if not a.Debug then return end;local f="[Cookieys Loader]: "if e then warn(f..tostring(d))else print(f..tostring(d))end end;local function g(h)if not b then return nil,"Executor does not support HTTP requests."end;local i;local j,k;for l=1,a.Retries do j,k=pcall(function()i=b({Url=h,Method="GET"})end)if j and i and i.StatusCode==200 and i.Body then return i.Body end;c("Connection failed (Attempt "..l.."/"..a.Retries..")... Retrying.",true)task.wait(1)end;return nil,"Failed to fetch URL after multiple attempts: "..tostring(h)end;if not game:IsLoaded()then game.Loaded:Wait()end;task.spawn(function()c("Fetching games list...")local m,n=g(a.Url)if not m then return c(n,true)end;local o=loadstring(m)if not o then return c("Syntax error in Games.lua file.",true)end;local p,q=pcall(o)if type(q)~="table"then return c("Games.lua did not return a valid table.",true)end;local r=game.PlaceId;local s=q[r]or q[tostring(r)]if not s then c("Specific game script not found. Checking for Universal...")s=q["Universal"]or q["universal"]end;if not s then return c("No supported script found for Game ID: "..r,true)end;c("Loading script from: "..s)local t,u=g(s)if not t then return c("Failed to download game script: "..tostring(u),true)end;local v,w=loadstring(t)if not v then return c("Syntax error in game script: "..tostring(w),true)end;task.spawn(v)c("Script executed successfully!")end)